head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05430.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.clickBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vAcptSeq = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = ""; // R=접수, H = 이력, N : 신규
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fr_SecuGrpId = SECUGRP_ID_BC;
scwin.vPageTYp = '1'; // 추가상장
scwin.vLIistMethdTpCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 상장구분코드

scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        btn_Search.trigger("onclick");
    }
};
scwin.fn_all_list_sync = function() {
    scwin.fn_recv_list_sync();
    scwin.fn_list_sync();
};
scwin.fn_recv_list_sync = function() {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&TRS_IDX=" + TRS_IDX_NEWSEL;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_BC_RECV + "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_Recv.DataID = encodeURI(url);
    dts_Recv.reset();
};
scwin.fn_list_sync = function() {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuIssChgList&DIV_IDX=" + DIV_IDX_CHG_ISS_BC_HIST + "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.fn_OpenDetailRecv = function(row) {
    scwin.vOpenTyp = "R";
    scwin.vLIistMethdTpCd = "2";
    scwin.clickBzProcsNo = dts_Recv.getCellData(row, "BZ_PROCS_NO");
    scwin.vAcptNo = dts_Recv.getCellData(row, "ACPT_NO");
    scwin.vIsurCd = dts_Recv.getCellData(row, "ISUR_CD");
    scwin.vAcptSeq = dts_Recv.getCellData(row, "BYACPTNO_SEQ");
    scwin.fn_OpenPopup();
};
scwin.fn_OpenDetailMng = function(row) {
    scwin.vAcptNo = ""; //초기화
    scwin.vLIistMethdTpCd = "";
    if (row > 0) {
        //그리드에서 선택시
        scwin.vOpenTyp = "H";
        scwin.fn_setBzProcsNo(row);
        scwin.vLIistMethdTpCd = dts_List.getCellData(row, "LIST_METHD_TP_CD");
    } else {
        //신규버튼 선택시
        scwin.vOpenTyp = "N";
        scwin.clickBzProcsNo = ""; //초기화
        scwin.vLIistMethdTpCd = "2";
    }
    scwin.fn_OpenPopup();
};
scwin.fn_OpenPopup = async function() {
    if (scwin.vLIistMethdTpCd == "2") {
        // 추가상장
        await $c.frame.CreateDialogFrame("ULDSTF05434.gfm", "/lstproc/ULDSTF05434.gfm", "수익증권 추가상장 관리", 200, 200, 620, 370, "window");
    } else {
        // 변경상장 및 신규상장
        await $c.frame.CreateDialogFrame("ULDSTF05414.gfm", "/lstproc/ULDSTF05414.gfm", "수익증권 변경상장 관리", 200, 200, 620, 310, "window");
    }
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
    scwin.vIsurCd = dts_List.getCellData(eval(obj), "ISUR_CD");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo + " vIsurCd:"+vIsurCd);

};
scwin.fn_getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};
scwin.img_ISU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    $c.lc.fn_PopFindIsu(scwin.fr_SecuGrpId);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) != "" && $c.stf.getObjectValue(txb_ISU_CD) != 'undefined') {
        scwin.fn_all_list_sync();
    } else {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
};
scwin.btn_New_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    scwin.fn_OpenDetailMng(-1);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List, "수익증권추가상장내역", "", "8");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_Recv_OnDblClick = function(row, colid) {
    if (dts_Recv.getTotalRow() > 0) {
        $c.elw.fn_OpenDetailRecv(row);
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (dts_List.getTotalRow() > 0 && row > 0) {
        scwin.fn_OpenDetailMng(row);
    }
};
scwin.dts_Recv_OnLoadError = function() {
    $c.stf.alert_error(dts_Recv);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    if ($c.stf.getObjectValue(txb_ISU_CD) != "" && $c.stf.getObjectValue(txb_ISU_CD) != 'undefined') {
        scwin.fn_recv_list_sync();
    }
};
